<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue'
import{ElMessage,ElMessageBox}from'element-plus'
import{useAuthStore}from'../../stores/auth'
import{admitPatient,createInpatient,dischargePatient,getInpatients,getOperationDepartments,getOperationDoctors,getPatients}from'../../services/operations'
import type{Department,DoctorSummary,InpatientAdmission,PatientSummary}from'../../types/medical'
const auth=useAuthStore(),canManage=computed(()=>auth.user?.role==='admin'||auth.user?.role==='doctor'),isPatient=computed(()=>auth.user?.role==='patient'),rows=ref<InpatientAdmission[]>([]),patients=ref<PatientSummary[]>([]),doctors=ref<DoctorSummary[]>([]),departments=ref<Department[]>([]),loading=ref(false),dialog=ref(false),saving=ref(false)
const form=reactive({patient_id:undefined as number|undefined,doctor_id:undefined as number|undefined,department_id:undefined as number|undefined,ward:'综合病区',bed_no:'',admission_diagnosis:''})
async function load(){loading.value=true;try{rows.value=(await getInpatients()).results}finally{loading.value=false}}
async function open(){Object.assign(form,{patient_id:undefined,doctor_id:undefined,department_id:undefined,ward:'综合病区',bed_no:'',admission_diagnosis:''});dialog.value=true;[patients.value,doctors.value,departments.value]=await Promise.all([getPatients(),getOperationDoctors(),getOperationDepartments()])}
async function submit(){if(!form.patient_id||!form.doctor_id||!form.department_id||!form.ward.trim()||!form.bed_no.trim()||!form.admission_diagnosis.trim()){ElMessage.warning('请完整填写住院信息');return}saving.value=true;try{await createInpatient(form);ElMessage.success('住院申请已创建');dialog.value=false;await load()}catch(e:any){ElMessage.error(e.response?.data?.detail||'创建失败')}finally{saving.value=false}}
async function admit(row:InpatientAdmission){try{await ElMessageBox.confirm(`确认为 ${row.patient_name} 办理入院？`,'办理入院');await admitPatient(row.id);ElMessage.success('入院办理完成');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.detail||'操作失败')}}
async function discharge(row:InpatientAdmission){try{const{value}=await ElMessageBox.prompt('填写诊疗经过、出院情况和随访建议','办理出院',{inputType:'textarea',inputValidator:value=>Boolean(value.trim())||'出院小结不能为空'});await dischargePatient(row.id,value.trim());ElMessage.success('出院办理完成');await load()}catch(e:any){if(e!=='cancel'&&e!=='close')ElMessage.error(e.response?.data?.detail||'操作失败')}}
onMounted(load)
</script>
<template><section><div class="page-heading"><div><p class="eyebrow">INPATIENT CARE</p><h1>{{isPatient?'我的住院记录':'住院管理'}}</h1><p>覆盖住院申请、床位信息、入院与出院小结</p></div><el-button v-if="canManage" type="primary" @click="open">＋ 住院申请</el-button></div><el-card class="table-card"><el-table v-loading="loading" :data="rows"><el-table-column prop="admission_no" label="住院号" min-width="150"/><el-table-column v-if="!isPatient" prop="patient_name" label="患者"/><el-table-column prop="department_name" label="科室"/><el-table-column prop="doctor_name" label="主治医师"/><el-table-column label="床位"><template #default="{row}">{{row.ward}} / {{row.bed_no}}</template></el-table-column><el-table-column prop="admission_diagnosis" label="入院诊断" min-width="200" show-overflow-tooltip/><el-table-column prop="status_display" label="状态"/><el-table-column v-if="canManage" label="操作" width="150"><template #default="{row}"><el-button v-if="row.status==='pending'" link type="primary" @click="admit(row)">办理入院</el-button><el-button v-if="row.status==='admitted'" link type="success" @click="discharge(row)">办理出院</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" title="创建住院申请" width="min(650px,94vw)"><el-form label-position="top"><el-row :gutter="14"><el-col :span="12"><el-form-item label="患者" required><el-select v-model="form.patient_id" filterable style="width:100%"><el-option v-for="item in patients" :key="item.id" :label="`${item.full_name} · ${item.patient_no}`" :value="item.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="主治医师" required><el-select v-model="form.doctor_id" filterable style="width:100%"><el-option v-for="item in doctors" :key="item.id" :label="`${item.full_name} · ${item.title}`" :value="item.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="科室" required><el-select v-model="form.department_id" style="width:100%"><el-option v-for="item in departments" :key="item.id" :label="item.name" :value="item.id"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="病区"><el-input v-model="form.ward"/></el-form-item></el-col><el-col :span="12"><el-form-item label="床位号" required><el-input v-model="form.bed_no"/></el-form-item></el-col></el-row><el-form-item label="入院诊断" required><el-input v-model="form.admission_diagnosis" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">提交申请</el-button></template></el-dialog></section></template>
